<?php
namespace Database\Seeders;use Illuminate\Database\Seeder;use App\Models\{User,Category,Product};use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;class DatabaseSeeder extends Seeder{public function run():void{foreach(['Électronique','Mode','Maison','Sports','Livres'] as $n)Category::firstOrCreate(['slug'=>Str::slug($n)],['name'=>$n,'is_active'=>true]);$cat=Category::first();foreach([['Smartphone Android',199,550000,12],['Casque Bluetooth',35,97000,20],['Montre connectée',59,165000,15],['Sac à dos',25,70000,18]] as [$n,$usd,$cdf,$stock])Product::firstOrCreate(['slug'=>Str::slug($n)],['category_id'=>$cat->id,'name'=>$n,'description'=>'Produit de démonstration à remplacer par votre catalogue réel.','price_usd'=>$usd,'price_cdf'=>$cdf,'stock'=>$stock,'condition'=>'new','is_active'=>true]);$email=env('ADMIN_EMAIL');$password=env('ADMIN_PASSWORD');if($email&&$password)User::updateOrCreate(['email'=>$email],['name'=>'Administrateur','password'=>Hash::make($password),'role'=>'admin']);}}
